<?php
declare(strict_types=1);
require __DIR__.'/../app/services/ProtectedRemoval.php';
class RemovalTestPDO extends PDO { public function prepare(string $sql,array $options=[]): PDOStatement|false { return parent::prepare(str_replace(' FOR UPDATE','',$sql),$options); } }
$db=new RemovalTestPDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec('CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT,email TEXT,role TEXT,is_active INTEGER,password_hash TEXT); CREATE TABLE members(id INTEGER PRIMARY KEY,first_name TEXT,last_name TEXT,email TEXT,status TEXT); CREATE TABLE member_portal_accounts(member_id INTEGER,password_hash TEXT,invitation_hash TEXT,invitation_expires_at TEXT); CREATE TABLE rooms(id INTEGER PRIMARY KEY,name TEXT); CREATE TABLE courses(id INTEGER PRIMARY KEY,title TEXT,room_id INTEGER,coach_id INTEGER,starts_at TEXT,ends_at TEXT,status TEXT,capacity INTEGER); CREATE TABLE course_bookings(id INTEGER PRIMARY KEY,course_id INTEGER,member_id INTEGER,status TEXT); CREATE TABLE activity_logs(user_id INTEGER,action TEXT,ip_address TEXT);');
foreach (['payments'=>'member_id INTEGER,subscription_id','attendance'=>'member_id','fitness_measurements'=>'member_id INTEGER,created_by','fitness_programs'=>'member_id INTEGER,created_by','marketing_consent_events'=>'member_id INTEGER,created_by','member_measurement_revisions'=>'member_id','shop_sales'=>'sold_by','stock_movements'=>'created_by','equipment_interventions'=>'created_by','expenses'=>'created_by','promotions'=>'created_by','subscription_freezes'=>'subscription_id INTEGER,state TEXT,resumed_on TEXT,credited_days INTEGER,created_by INTEGER,closed_by','payment_refunds'=>'created_by','gym_settings'=>'updated_by'] as $table=>$columns) $db->exec('CREATE TABLE '.$table.' ('.$columns.' INTEGER)');
