$adminHash=password_hash('mot de passe admin 123!',PASSWORD_DEFAULT); $coachHash=password_hash('mot de passe coach 123!',PASSWORD_DEFAULT); $db->prepare("INSERT INTO users VALUES(1,'Admin','admin@example.tn','Admin',1,?),(2,'Coach','coach@example.tn','Coach',1,?),(3,'Coach lié','linked@example.tn','Coach',1,?)")->execute([$adminHash,$coachHash,$coachHash]);
$db->exec("INSERT INTO members VALUES(1,'Sans','Historique','one@example.tn','active'),(2,'Avec','Historique','two@example.tn','active'),(3,'Liste','Noire','three@example.tn','blacklisted'),(4,'Autre','Libre','four@example.tn','active'); INSERT INTO subscriptions VALUES(10,2,1,'2029-01-01','2029-12-31','active','20.000'); INSERT INTO member_portal_accounts VALUES(2,'old-hash','invite','2030-01-01'); INSERT INTO rooms VALUES(1,'Libre'),(2,'Occupée'); INSERT INTO courses VALUES(1,'Libre',2,NULL,'2031-01-01 10:00:00','2031-01-01 11:00:00','scheduled',10),(2,'Inscrit',2,NULL,'2031-01-02 10:00:00','2031-01-02 11:00:00','scheduled',10),(3,'Passé',2,NULL,'2029-01-01 10:00:00','2029-01-01 11:00:00','scheduled',10),(4,'Coaching',2,3,'2031-01-03 10:00:00','2031-01-03 11:00:00','scheduled',10); INSERT INTO course_bookings VALUES(1,2,2,'confirmed');");
$svc=new ProtectedRemoval($db,1,'127.0.0.1'); $password='mot de passe admin 123!'; $now=new DateTimeImmutable('2030-01-01');
$versions=static function(string $type) use($svc): array { $map=[]; foreach ($svc->listing($type,'',1)['rows'] as $r) $map[$r['id']]=$r['version']; return $map; };
$reject=static function(callable $fn): void { try { $fn(); } catch (DomainException $e) { return; } throw new RuntimeException('Action invalide acceptée'); };
$v=$versions('members'); $reject(fn()=>$svc->execute('members',['1'],$v,'incorrect',$now)); $reject(fn()=>$svc->execute('members',['1','1'],$v,$password,$now)); $reject(fn()=>$svc->execute('members',['1'],[1=>str_repeat('0',64)],$password,$now));
$out=$svc->execute('members',['1','2'],$v,$password,$now);
if ($out[1]!=='supprimé' || !str_contains($out[2],'désactivé') || $db->query('SELECT status FROM members WHERE id=2')->fetchColumn()!=='inactive' || $db->query('SELECT password_hash FROM member_portal_accounts WHERE member_id=2')->fetchColumn()==='old-hash' || $db->query('SELECT invitation_hash FROM member_portal_accounts WHERE member_id=2')->fetchColumn()!==null) throw new RuntimeException('Membre : protection incorrecte');
$out=$svc->execute('members',['3'],$versions('members'),$password,$now); if ($out[3]!=='liste noire conservée' || $db->query('SELECT status FROM members WHERE id=3')->fetchColumn()!=='blacklisted') throw new RuntimeException('Liste noire supprimée');
$v=$versions('rooms'); $reject(fn()=>$svc->execute('rooms',['1','2'],$v,$password,$now)); if ((int)$db->query('SELECT COUNT(*) FROM rooms')->fetchColumn()!==2) throw new RuntimeException('Lot partiel');
$out=$svc->execute('rooms',['1'],$v,$password,$now); if ($out[1]!=='supprimée') throw new RuntimeException('Salle non supprimée');
$v=$versions('courses'); $out=$svc->execute('courses',['1','2'],$v,$password,$now); if ($out[1]!=='supprimé' || !str_contains($out[2],'annulé') || $db->query('SELECT status FROM course_bookings WHERE id=1')->fetchColumn()!=='cancelled') throw new RuntimeException('Cours ou réservations incorrects');
$reject(fn()=>$svc->execute('courses',['3'],$versions('courses'),$password,$now));
$v=$versions('coaches'); $reject(fn()=>$svc->execute('coaches',['3'],$v,$password,$now)); $out=$svc->execute('coaches',['2'],$v,$password,$now); if ($out[2]!=='supprimé') throw new RuntimeException('Coach libre non supprimé');
$db->exec("UPDATE courses SET status='cancelled' WHERE id=4"); $out=$svc->execute('coaches',['3'],$versions('coaches'),$password,$now); if (!str_contains($out[3],'désactivé') || $db->query('SELECT is_active FROM users WHERE id=3')->fetchColumn()!==0) throw new RuntimeException('Coach avec historique non désactivé');
// Abonnements : suppression d'une future adhésion vide, annulation avec historique et protection des expirés.
$db->exec("INSERT INTO subscriptions VALUES(11,4,1,'2031-01-01','2031-01-31','active','40.000'),(12,4,1,'2030-01-01','2030-01-31','frozen','50.000'),(13,4,1,'2028-01-01','2028-02-01','active','20.000'); INSERT INTO payments(member_id,subscription_id) VALUES(4,12); INSERT INTO subscription_freezes(subscription_id,state,created_by) VALUES(12,'open',1)");
$v=$versions('subscriptions'); $out=$svc->execute('subscriptions',['11','12','13'],$v,$password,$now);
if ($out[11]!=='supprimé' || !str_contains($out[12],'annulé') || $out[13]!=='historique expiré conservé' || $db->query('SELECT status FROM subscriptions WHERE id=12')->fetchColumn()!=='cancelled' || $db->query('SELECT state FROM subscription_freezes WHERE subscription_id=12')->fetchColumn()!=='cancelled' || (int)$db->query('SELECT COUNT(*) FROM payments WHERE subscription_id=12')->fetchColumn()!==1) throw new RuntimeException('Protection des abonnements incorrecte');
$single=$svc->one('subscriptions',12); if (!$single || $svc->versionFor('subscriptions',$single)!==$single['version'] || $svc->one('subscriptions',999)!==null) throw new RuntimeException('Sélection directe incorrecte');
$db->exec("INSERT INTO subscriptions VALUES(14,4,1,'2031-03-01','2031-03-31','active','20.000'); DROP TABLE subscription_discounts");
try { $svc->execute('subscriptions',['14'],$versions('subscriptions'),$password,$now); throw new RuntimeException('Dépendance absente acceptée'); } catch (PDOException $e) {}
if ((int)$db->query('SELECT COUNT(*) FROM subscriptions WHERE id=14')->fetchColumn()!==1) throw new RuntimeException('Suppression malgré migration absente');
$db->exec("INSERT INTO rooms VALUES(9,'Libre'); DROP TABLE activity_logs"); try { $svc->execute('rooms',['9'],$versions('rooms'),$password,$now); throw new RuntimeException('Audit absent accepté'); } catch (PDOException $e) {}
if ((int)$db->query('SELECT COUNT(*) FROM rooms WHERE id=9')->fetchColumn()!==1) throw new RuntimeException('Rollback absent');
echo "Suppressions protégées : lots, historiques, accès, conflits et rollback OK\n";
